<template><ion-page><ion-content><main class="auth-shell"><section class="auth-panel"><ion-button fill="clear" router-link="/login"><ion-icon slot="start" :icon="arrowBackOutline"/>Voltar</ion-button><div class="role-badge">Segurança</div><h1>Recupere sua senha</h1><p>Enviaremos um link de redefinição para seu e-mail.</p><form @submit.prevent="enviar"><ion-input v-model="email" type="email" label="E-mail cadastrado" label-placement="stacked" fill="outline" required/><p v-if="erro" class="error">{{erro}}</p><ion-button type="submit" expand="block" :disabled="carregando">{{carregando?'Enviando...':'Enviar link'}}</ion-button></form></section></main></ion-content></ion-page></template>
<script setup lang="ts">import { ref } from 'vue';import { useRouter } from 'vue-router';import { IonButton,IonContent,IonIcon,IonInput,IonPage,toastController } from '@ionic/vue';import { arrowBackOutline } from 'ionicons/icons';import { recuperarSenha,mensagemAuth } from '../services/auth.service';const router=useRouter(),email=ref(''),erro=ref(''),carregando=ref(false);async function enviar(){erro.value='';carregando.value=true;try{await recuperarSenha(email.value);const toast=await toastController.create({message:'Se este e-mail estiver cadastrado, enviaremos um link de recuperação. Confira também a caixa de spam.',duration:3500,color:'success',position:'top'});await toast.present();await router.replace('/login')}catch(e){erro.value=mensagemAuth(e)}finally{carregando.value=false}}</script>
